// All timesheet data, and the only code that changes it.
//
// Time is kept in two layers that may overlap:
// - "days": the blocks you log yourself (manual blocks). Editable. They never
//   overlap each other. A manual block may have countExtra: false, meaning its
//   time outside the journal blocks is not counted.
// - "journal": blocks imported from Revit journals: the evidence. Not editable;
//   a journal block can only be excluded from totals (excluded: true) or given
//   your own remark (userNote). Its "note" is generated by the import.
// accounting.js works out what counts, without double counting where they overlap.
//
// Shape of timesheet.json:
// {
//   "labels":  { "Thomas Street": { "color": "#1D9E75", "lastUsed": 1763700000000 } },
//   "days":    { "2026-11-21": [ { "start": 540, "end": 690, "label": "Thomas Street", "note": "…" } ] },
//   "journal": { "2026-11-18": [ { "start": 585, "end": 1110, "label": "Thomas Street", "note": "…",
//                                  "activity": { … } } ] },
//   "importedSessions": { "2026-11-18T08:44:58": { "label": "Thomas Street", "importedAt": 1763… } },
//   "settings": { "countNoFileTime": true }
// }
// start/end are minutes from midnight, always on 15-minute boundaries.
// Notes are free text and may contain links. A journal block's "activity" holds
// which files were worked in, per 5 minutes, { start, binMinutes, files, bins,
// actions }, where start is the minute of day of the first bin.

export const SLOT_MINUTES = 15;
export const SLOTS_PER_DAY = (24 * 60) / SLOT_MINUTES;

// Colours handed out to new labels in order (changeable later from the summary).
const LABEL_PALETTE = [
  '#1D9E75', '#378ADD', '#EF9F27', '#D85A30', '#639922', '#5DCAA5',
  '#185FA5', '#BA7517', '#E24B4A', '#0F6E56', '#85B7EB', '#888780',
];
const FALLBACK_COLOR = '#888780';
const SAVE_DELAY_MS = 400;

// Where data is kept: 'server' writes timesheet.json through server.js;
// 'browser' is the fallback when no server answers (e.g. the GitHub Pages copy)
// and keeps the data in this browser's localStorage.
const BROWSER_STORAGE_KEY = 'freelancalot.data';
const API_URL = 'api/data'; // relative, so it also resolves under a sub-path

let data = { labels: {}, days: {} };
let storageMode = 'server';
let saveTimer = null;
let statusListener = () => {};
let changeListener = () => {};

// ---------- loading and saving ----------

export async function loadData() {
  try {
    const response = await fetch(API_URL);
    if (!response.ok) throw new Error(`No server (${response.status})`);
    setData(await response.json());
  } catch {
    storageMode = 'browser';
    const stored = localStorage.getItem(BROWSER_STORAGE_KEY);
    setData(stored ? JSON.parse(stored) : {});
  }
}

export function getStorageMode() { return storageMode; }
export function onSaveStatus(listener) { statusListener = listener; }
export function onChange(listener) { changeListener = listener; }

function setData(loaded) {
  data = {
    labels: loaded.labels ?? {},
    days: loaded.days ?? {},
    journal: loaded.journal ?? {},
    importedSessions: loaded.importedSessions ?? {},
    settings: loaded.settings ?? {},
  };
  moveImportedBlocksToJournal();
}

// Older timesheets kept imported blocks among the manual ones; they are
// recognised by their file activity and moved to the journal layer.
function moveImportedBlocksToJournal() {
  for (const [key, entries] of Object.entries(data.days)) {
    const imported = entries.filter((entry) => entry.activity);
    if (imported.length === 0) continue;
    data.journal[key] = [...(data.journal[key] ?? []), ...imported].sort((a, b) => a.start - b.start);
    const manual = entries.filter((entry) => !entry.activity);
    if (manual.length) data.days[key] = manual;
    else delete data.days[key];
  }
}

// ---------- settings saved with the data ----------

// Whether quarter-hours in Revit with no file loaded (from journal activity)
// count towards totals. On unless switched off.
export function countsNoFileTime() {
  return data.settings?.countNoFileTime !== false;
}

export function setCountNoFileTime(count) {
  data.settings = { ...data.settings, countNoFileTime: count };
  dataChanged();
}

function dataChanged() {
  changeListener();
  statusListener('saving');
  clearTimeout(saveTimer);
  saveTimer = setTimeout(saveNow, SAVE_DELAY_MS);
}

async function saveNow() {
  try {
    if (storageMode === 'browser') {
      localStorage.setItem(BROWSER_STORAGE_KEY, JSON.stringify(data));
    } else {
      const response = await fetch(API_URL, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error(`Save failed (${response.status})`);
    }
    statusListener('saved');
  } catch (error) {
    console.error(error);
    statusListener('error');
  }
}

// Remove all logged time and all labels.
export function clearAll() {
  setData({});
  dataChanged();
}

// ---------- export and import (a timesheet.json file) ----------

export function exportJson() {
  return JSON.stringify(data, null, 2);
}

// Replaces all current data with the file's contents.
export function importJson(text) {
  const loaded = JSON.parse(text);
  if (typeof loaded?.labels !== 'object' || typeof loaded?.days !== 'object') {
    throw new Error('Not a timesheet file: expected { labels, days }');
  }
  setData(loaded);
  dataChanged();
}

// ---------- reading ----------

export function getEntries(key) {
  return data.days[key] ?? [];
}

export function getLabelColor(name) {
  return data.labels[name]?.color ?? FALLBACK_COLOR;
}

// One { label, note, countExtra } (or null) per 15-minute slot of the day,
// for the manual blocks.
function getSlots(key) {
  const slots = new Array(SLOTS_PER_DAY).fill(null);
  for (const entry of getEntries(key)) {
    const value = { label: entry.label, note: entry.note ?? '', activity: entry.activity, countExtra: entry.countExtra !== false };
    for (let slot = entry.start / SLOT_MINUTES; slot < entry.end / SLOT_MINUTES; slot++) slots[slot] = value;
  }
  return slots;
}

// One label (or null) per 15-minute slot of the day.
export function getSlotLabels(key) {
  return getSlots(key).map((slot) => slot?.label ?? null);
}

// The block (entry) covering a slot, or null.
export function findEntryAt(key, slot) {
  const minute = slot * SLOT_MINUTES;
  return getEntries(key).find((entry) => entry.start <= minute && minute < entry.end) ?? null;
}

// Quarter-hours of a block (minute of day of each) in which Revit had no file
// loaded: the journal names no file in them. Only for blocks with journal activity.
export function noFileSlots(entry) {
  const activity = entry.activity;
  if (!activity) return [];
  const step = activity.binMinutes ?? SLOT_MINUTES;
  const empty = [];
  for (let slotStart = entry.start; slotStart < entry.end; slotStart += SLOT_MINUTES) {
    let mentions = 0;
    for (let minute = slotStart; minute < slotStart + SLOT_MINUTES; minute += step) {
      const counts = activity.bins[(minute - activity.start) / step];
      if (counts) mentions += counts.reduce((sum, count) => sum + count, 0);
    }
    if (mentions === 0) empty.push(slotStart);
  }
  return empty;
}

export function noFileMinutes(entry) {
  return noFileSlots(entry).length * SLOT_MINUTES;
}

// Existing labels matching the typed text: names starting with it first,
// then names containing it; most recently used first within each group.
export function suggestLabels(text) {
  const query = text.trim().toLowerCase();
  const byRecency = (a, b) => (b[1].lastUsed ?? 0) - (a[1].lastUsed ?? 0);
  const entries = Object.entries(data.labels).sort(byRecency);
  const startsWith = entries.filter(([name]) => name.toLowerCase().startsWith(query));
  const contains = entries.filter(([name]) => !name.toLowerCase().startsWith(query) && name.toLowerCase().includes(query));
  return [...startsWith, ...contains].map(([name]) => name);
}

export function labelExists(name) {
  return Object.prototype.hasOwnProperty.call(data.labels, name);
}

// ---------- changing ----------

// Give slots firstSlot..lastSlot (inclusive) a label, or clear them with label = null.
// Slots that already had this label keep their note; newly labelled slots take
// the note of a same-label block they touch, so extending a block keeps its note.
export function assignSlots(key, firstSlot, lastSlot, label) {
  const slots = getSlots(key);
  const note = label ? noteToInherit(slots, firstSlot, lastSlot, label) : '';
  for (let slot = firstSlot; slot <= lastSlot; slot++) {
    if (!label) slots[slot] = null;
    else if (slots[slot]?.label !== label) slots[slot] = { label, note };
  }
  storeSlots(key, slots);
  if (label) markLabelUsed(label);
  dataChanged();
}

export function getLabelNames() {
  return Object.keys(data.labels);
}

// Whether a manual block's time outside the journal blocks counts.
export function setCountExtra(key, slot, countExtra) {
  const slots = getSlots(key);
  const [first, last] = blockRange(slots, slot);
  if (first === null) return;
  const updated = { ...slots[first], countExtra };
  for (let s = first; s <= last; s++) slots[s] = updated;
  storeSlots(key, slots);
  dataChanged();
}

export function setNote(key, slot, note) {
  const slots = getSlots(key);
  const [first, last] = blockRange(slots, slot);
  if (first === null) return;
  const updated = { ...slots[first], note: note.trim() };
  for (let s = first; s <= last; s++) slots[s] = updated;
  storeSlots(key, slots);
  dataChanged();
}

export function deleteBlock(key, slot) {
  const slots = getSlots(key);
  const [first, last] = blockRange(slots, slot);
  if (first === null) return;
  for (let s = first; s <= last; s++) slots[s] = null;
  storeSlots(key, slots);
  dataChanged();
}

// Boundary b is where slot b-1 meets slot b (0..SLOTS_PER_DAY).
// It is a block edge when the slots on either side differ.
export function isBlockEdge(key, boundary) {
  const slots = getSlots(key);
  return !sameSlot(slots[boundary - 1], slots[boundary]);
}

// How far a block edge may move: until the block on either side would vanish
// (each keeps at least one slot); empty time on either side may be used up.
export function boundaryLimits(key, boundary) {
  return limitsOfBoundary(getSlots(key), boundary);
}

// Drag a block edge to newBoundary: the side it moves into takes over those slots.
export function moveBoundary(key, boundary, newBoundary) {
  const slots = getSlots(key);
  const [min, max] = limitsOfBoundary(slots, boundary);
  const target = Math.min(Math.max(newBoundary, min), max);
  if (target === boundary) return;
  if (target > boundary) {
    for (let slot = boundary; slot < target; slot++) slots[slot] = slots[boundary - 1];
  } else {
    for (let slot = target; slot < boundary; slot++) slots[slot] = slots[boundary];
  }
  storeSlots(key, slots);
  dataChanged();
}

// How many slots the block at `slot` can move up (negative) or down (positive)
// without running into another block or past the start/end of the day.
export function blockMoveLimits(key, slot) {
  return limitsOfBlockMove(getSlots(key), slot);
}

// Move a whole block (label and note) by delta slots; the time it leaves is emptied.
export function moveBlock(key, slot, delta) {
  const slots = getSlots(key);
  const [first, last] = blockRange(slots, slot);
  if (first === null) return;
  const [minDelta, maxDelta] = limitsOfBlockMove(slots, slot);
  const shift = Math.min(Math.max(delta, minDelta), maxDelta);
  if (shift === 0) return;
  // The block's file activity moves with it (it is stored by time of day).
  const moved = slots[first];
  const activity = moved.activity && { ...moved.activity, start: moved.activity.start + shift * SLOT_MINUTES };
  const block = { ...moved, activity };
  for (let s = first; s <= last; s++) slots[s] = null;
  for (let s = first + shift; s <= last + shift; s++) slots[s] = block;
  storeSlots(key, slots);
  dataChanged();
}

function limitsOfBlockMove(slots, slot) {
  const [first, last] = blockRange(slots, slot);
  if (first === null) return [0, 0];
  let freeBefore = 0;
  while (first - freeBefore - 1 >= 0 && !slots[first - freeBefore - 1]) freeBefore++;
  let freeAfter = 0;
  while (last + freeAfter + 1 < slots.length && !slots[last + freeAfter + 1]) freeAfter++;
  return [-freeBefore, freeAfter];
}

function limitsOfBoundary(slots, boundary) {
  const left = slots[boundary - 1] ?? null;
  const right = slots[boundary] ?? null;
  let leftRunStart = boundary;
  while (leftRunStart > 0 && sameSlot(slots[leftRunStart - 1], left)) leftRunStart--;
  let rightRunEnd = boundary;
  while (rightRunEnd < slots.length && sameSlot(slots[rightRunEnd], right)) rightRunEnd++;
  return [left ? leftRunStart + 1 : leftRunStart, right ? rightRunEnd - 1 : rightRunEnd];
}

// Two slots are the same when both are empty, or both have the same label and note.
function sameSlot(a, b) {
  const first = a ?? null;
  const second = b ?? null;
  if (first === null || second === null) return first === second;
  return first.label === second.label && first.note === second.note
    && first.activity === second.activity && first.countExtra === second.countExtra;
}

// All file activity in the data (for giving every file one colour everywhere).
export function getAllActivity() {
  return Object.values(data.journal).flat().map((entry) => entry.activity).filter(Boolean);
}

// ---------- the journal layer (imported from Revit journals) ----------

export function getJournalEntries(key) {
  return data.journal[key] ?? [];
}

export function findJournalEntryAt(key, slot) {
  const minute = slot * SLOT_MINUTES;
  return getJournalEntries(key).find((entry) => entry.start <= minute && minute < entry.end) ?? null;
}

export function isSessionImported(sessionId) {
  return Boolean(data.importedSessions[sessionId]);
}

export function importedSessionCount() {
  return Object.keys(data.importedSessions).length;
}

// Add imported blocks [{ start, end, note, activity }] to a day's journal layer.
// They only fill time no journal block covers yet (manual blocks don't matter
// here: the layers may overlap). Returns minutes added and skipped.
export function addJournalBlocks(key, label, blocks) {
  const taken = new Set();
  for (const entry of getJournalEntries(key)) {
    for (let minute = entry.start; minute < entry.end; minute += SLOT_MINUTES) taken.add(minute);
  }
  const added = [];
  let skipped = 0;
  for (const block of blocks) {
    let runStart = null;
    const closeRun = (end) => {
      if (runStart === null) return;
      const entry = { start: runStart, end, label, note: (block.note ?? '').trim() };
      if (block.activity) entry.activity = block.activity;
      added.push(entry);
      runStart = null;
    };
    for (let minute = block.start; minute < block.end; minute += SLOT_MINUTES) {
      if (taken.has(minute)) {
        skipped += SLOT_MINUTES;
        closeRun(minute);
      } else if (runStart === null) {
        runStart = minute;
      }
    }
    closeRun(block.end);
  }
  if (added.length) {
    data.journal[key] = [...getJournalEntries(key), ...added].sort((a, b) => a.start - b.start);
    markLabelUsed(label);
    dataChanged();
  }
  return { added: added.reduce((sum, entry) => sum + entry.end - entry.start, 0), skipped };
}

// Remove a label's journal blocks on a day (before importing those sessions again).
export function removeJournalBlocks(key, label) {
  const kept = getJournalEntries(key).filter((entry) => entry.label !== label);
  if (kept.length) data.journal[key] = kept;
  else delete data.journal[key];
  dataChanged();
}

export function markSessionsImported(sessionIds, label) {
  const importedAt = Date.now();
  for (const id of sessionIds) data.importedSessions[id] = { label, importedAt };
  dataChanged();
}

// A journal block can't be edited, only left out of the totals…
export function setJournalExcluded(key, start, excluded) {
  const entry = getJournalEntries(key).find((candidate) => candidate.start === start);
  if (!entry) return;
  if (excluded) entry.excluded = true;
  else delete entry.excluded;
  dataChanged();
}

// …or given your own remark, kept apart from the generated note.
export function setJournalUserNote(key, start, text) {
  const entry = getJournalEntries(key).find((candidate) => candidate.start === start);
  if (!entry) return;
  if (text.trim()) entry.userNote = text.trim();
  else delete entry.userNote;
  dataChanged();
}

function noteToInherit(slots, firstSlot, lastSlot, label) {
  const candidates = [firstSlot - 1, lastSlot + 1];
  for (let slot = firstSlot; slot <= lastSlot; slot++) candidates.push(slot);
  const match = candidates.find((slot) => slots[slot]?.label === label);
  return match === undefined ? '' : slots[match].note;
}

// First and last slot of the block (same label, note and activity) around a slot.
function blockRange(slots, slot) {
  if (!slots[slot]) return [null, null];
  const same = (s) => slots[s] && sameSlot(slots[s], slots[slot]);
  let first = slot;
  let last = slot;
  while (first > 0 && same(first - 1)) first--;
  while (last < slots.length - 1 && same(last + 1)) last++;
  return [first, last];
}

function storeSlots(key, slots) {
  const entries = slotsToEntries(slots);
  if (entries.length) data.days[key] = entries;
  else delete data.days[key];
}

export function setLabelColor(name, color) {
  if (!data.labels[name]) return;
  data.labels[name].color = color;
  dataChanged();
}

// Rename a label everywhere. Renaming to a name that already exists merges
// the two: all time moves to the existing label, which keeps its colour.
export function renameLabel(oldName, newName) {
  if (!labelExists(oldName) || !newName || oldName === newName) return;

  if (labelExists(newName)) {
    data.labels[newName].lastUsed = Math.max(data.labels[newName].lastUsed ?? 0, data.labels[oldName].lastUsed ?? 0);
  } else {
    data.labels[newName] = data.labels[oldName];
  }
  delete data.labels[oldName];

  for (const key of Object.keys(data.days)) {
    const slots = getSlots(key).map((slot) => (slot?.label === oldName ? { ...slot, label: newName } : slot));
    storeSlots(key, slots); // re-joins blocks that now touch (if their notes match)
  }
  for (const entry of Object.values(data.journal).flat()) {
    if (entry.label === oldName) entry.label = newName;
  }
  for (const session of Object.values(data.importedSessions)) {
    if (session.label === oldName) session.label = newName;
  }
  dataChanged();
}

function markLabelUsed(name) {
  if (!data.labels[name]) data.labels[name] = { color: pickNewLabelColor() };
  data.labels[name].lastUsed = Date.now();
}

function pickNewLabelColor() {
  const usedColors = new Set(Object.values(data.labels).map((label) => label.color));
  const unused = LABEL_PALETTE.find((color) => !usedColors.has(color));
  return unused ?? LABEL_PALETTE[Object.keys(data.labels).length % LABEL_PALETTE.length];
}

// Collapse runs of equal slots (same label and note) into entries.
function slotsToEntries(slots) {
  const entries = [];
  let runStart = 0;
  while (runStart < slots.length) {
    const slot = slots[runStart];
    let runEnd = runStart;
    while (runEnd < slots.length && sameSlot(slots[runEnd], slot)) runEnd++;
    if (slot) {
      const entry = { start: runStart * SLOT_MINUTES, end: runEnd * SLOT_MINUTES, label: slot.label };
      if (slot.note) entry.note = slot.note;
      if (slot.activity) entry.activity = slot.activity;
      if (slot.countExtra === false) entry.countExtra = false;
      entries.push(entry);
    }
    runStart = runEnd;
  }
  return entries;
}
